import importlib.util,json,sys
s=importlib.util.spec_from_file_location('vm','benchmark/writing/verify_method.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
r=json.loads(m.read_repository(m.REVIEW_PATH));p=json.loads(m.read_repository(m.PROPOSAL_PATH))
h={q:x for q,x in {**p['input_pins'],**p['supplementary_pins']}.items() if q not in m.CHANGED_EXISTING}
h[m.PROPOSAL_PATH]={'size':20557,'sha256':m.PROPOSAL_SHA256}
for q,x in r['scoped_files'].items(): h[q]={'size':x['size'],'sha256':x['sha256']}
for q,x in m.EXTRA_HISTORICAL.items(): h[q]={'sha256':x}
print(len(h))
for q,x in h.items():
  a=m.file_pin(q)
  if a['sha256']!=x['sha256'] or ('size' in x and a['size']!=x['size']): print('MISMATCH',q,x,a)
prov=json.loads(m.read_repository(m.PROVENANCE_PATH))
for q,x in prov['outputs'].items():
  a=m.file_pin(q)
  if a!=x: print('OUT MISMATCH',q,x,a)
"
